const pool = require('../config/database');
const bcrypt = require('bcrypt');

class User {
    static async create({ username, email, password, type, displayName, department, role = 'user' }) {
        const hashedPassword = await bcrypt.hash(password, 10);

        const [result] = await pool.query(
            `INSERT INTO users (username, email, password, type, display_name, department, role)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [username, email, hashedPassword, type, displayName, department, role]
        );

        return result.insertId;
    }

    static async findByUsername(username) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE username = ? AND status = 1',
            [username]
        );
        return rows[0];
    }

    static async findByEmail(email) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE email = ? AND status = 1',
            [email]
        );
        return rows[0];
    }

    static async findById(id) {
        const [rows] = await pool.query(
            'SELECT * FROM users WHERE id = ? AND status = 1',
            [id]
        );
        return rows[0];
    }

    static async verifyPassword(plainPassword, hashedPassword) {
        return bcrypt.compare(plainPassword, hashedPassword);
    }

    static async updateLastLogin(userId) {
        await pool.query(
            'UPDATE users SET last_login = NOW() WHERE id = ?',
            [userId]
        );
    }

    static sanitizeUser(user) {
        if (!user) return null;

        const { password, ...safeUser } = user;
        return safeUser;
    }
}

module.exports = User;

const XMLBuilder = require('./xmlBuilder');
const XMLSigner = require('./xmlSigner');

class ResponseBuilder {
    constructor(config) {
        this.issuer = config.issuer;
        this.certificate = config.certificate;
        this.privateKey = config.privateKey;
        this.signer = new XMLSigner(this.privateKey, this.certificate);
    }

    buildLoginResponse(options) {
        const {
            inResponseTo,
            destination,
            nameID,
            nameIDFormat = 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes = [],
            sessionIndex,
            audience
        } = options;

        const responseID = XMLBuilder.generateID();
        const assertionID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();
        const notBefore = issueInstant;
        const notOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const subjectNotOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const finalSessionIndex = sessionIndex || XMLBuilder.generateID();

        const responseWithoutAssertion = XMLBuilder.buildResponseWithoutAssertion({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode: 'urn:oasis:names:tc:SAML:2.0:status:Success'
        });

        const assertion = XMLBuilder.buildAssertion({
            assertionID,
            issueInstant,
            issuer: this.issuer,
            nameID,
            nameIDFormat,
            recipient: destination,
            audience: audience || destination,
            inResponseTo,
            sessionIndex: finalSessionIndex,
            attributes,
            notBefore,
            notOnOrAfter,
            subjectNotOnOrAfter
        });

        const signedAssertion = this.signer.signAssertion(assertion, assertionID);

        const signedResponse = this.signer.signResponse(
            responseWithoutAssertion,
            responseID,
            signedAssertion
        );

        return signedResponse;
    }

    buildLogoutResponse(options) {
        const {
            inResponseTo,
            destination,
            statusCode = 'urn:oasis:names:tc:SAML:2.0:status:Success'
        } = options;

        const responseID = XMLBuilder.generateID();
